// Create a function that decodes with configurable error handling and BOM behavior
function safeDecode(uint8arr, options = {}) {
    const { fatal = false, keepBOM = false } = options;
    const dec = new TextDecoder('utf-8', { fatal, ignoreBOM: keepBOM });
    try {
        return { text: dec.decode(uint8arr), error: null };
    } catch (e) {
        return { text: null, error: e.message };
    }
}

