// Hash utility library: each function hashes data and returns
// { hash, algorithm, encoding, inputLength }

function hashHex(algorithm, data) {
    const h = crypto.createHash(algorithm).update(data).digest('hex');
    return {
        hash: h,
        algorithm,
        encoding: 'hex',
        inputLength: Buffer.byteLength(data)
    };
}

