const assert = require('assert');

// Number formatting utility using Intl.NumberFormat
// Returns { formatted, parts } where parts is from formatToParts

function formatCurrency(amount, currency, locale) {
    const fmt = new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currency
    });
    const parts = fmt.formatToParts(amount);
    return {
        formatted: fmt.format(amount),
        parts: parts.map(p => ({ type: p.type, value: p.value }))
    };
}

// US dollar formatting
const usd = formatCurrency(1234.56, 'USD', 'en-US');
assert.strictEqual(usd.formatted, '$1,234.56');
// Parts include: currency, integer, group, decimal, fraction
assert.ok(usd.parts.some(p => p.type === 'currency' && p.value === '$'));
assert.ok(usd.parts.some(p => p.type === 'group' && p.value === ','));
assert.ok(usd.parts.some(p => p.type === 'decimal' && p.value === '.'));

