function parseDuration(str) {
    const re = /^(?<hours>\d+)h(?<minutes>\d+)m(?<seconds>\d+)s$/;
    const m = str.match(re);
    if (!m) return null;
    return {
        hours: parseInt(m.groups.hours, 10),
        minutes: parseInt(m.groups.minutes, 10),
        seconds: parseInt(m.groups.seconds, 10),
        totalSeconds: parseInt(m.groups.hours, 10) * 3600 +
                      parseInt(m.groups.minutes, 10) * 60 +
                      parseInt(m.groups.seconds, 10),
        raw: m[0]
    };
}

