const assert = require('assert');

// Locale-aware string sorting utilities using Intl.Collator
// Each function returns { sorted, locale, options }

function sortCaseSensitive(arr, locale) {
    const collator = new Intl.Collator(locale, { sensitivity: 'case' });
    const sorted = [...arr].sort(collator.compare);
    return { sorted, locale, options: { sensitivity: 'case' } };
}

// Case-sensitive sort groups by case
const cs1 = sortCaseSensitive(['banana', 'Apple', 'cherry', 'apple'], 'en');
// Intl.Collator with sensitivity:'case' treats accents as equal but case differs
assert.strictEqual(cs1.locale, 'en');

function sortCaseInsensitive(arr, locale) {
    const collator = new Intl.Collator(locale, { sensitivity: 'base' });
    const sorted = [...arr].sort(collator.compare);
    return { sorted, locale, options: { sensitivity: 'base' } };
}

// Base sensitivity: accents and case are ignored
const ci1 = sortCaseInsensitive(['B', 'a', 'C'], 'en');
assert.deepStrictEqual(ci1.sorted, ['a', 'B', 'C']);

golden_completion:
function sortNatural(arr, locale) {
    const collator = new Intl.Collator(locale, { numeric: true, sensitivity: 'base' });
    const sorted = [...arr].sort(collator.compare);
    return { sorted, locale, options: { numeric: true, sensitivity: 'base' } };
}

suffix:
// sortNatural uses numeric: true for natural number ordering
// "file2" comes before "file10" (unlike lexicographic sort)
const ns1 = sortNatural(['file10', 'file2', 'file1', 'file20'], 'en');
assert.deepStrictEqual(ns1.sorted, ['file1', 'file2', 'file10', 'file20']);
assert.strictEqual(ns1.locale, 'en');
assert.strictEqual(ns1.options.numeric, true);

// Numeric sort with mixed strings
const ns2 = sortNatural(['item3', 'item1', 'item11', 'item2'], 'en');
assert.deepStrictEqual(ns2.sorted, ['item1', 'item2', 'item3', 'item11']);

// Case insensitive due to sensitivity: 'base'
// With numeric: true, 'a' and 'A' are equivalent (base), so a1 < A10 < b1 < B2
const ns3 = sortNatural(['B2', 'a1', 'A10', 'b1'], 'en');
assert.deepStrictEqual(ns3.sorted, ['a1', 'A10', 'b1', 'B2']);

